  'help.question.createWallet': 'Como crio uma carteira?',
  'help.answer.createWallet': 'Sua carteira é criada automaticamente quando você se registra. Você pode ver o saldo da sua carteira na tela inicial.',
  'help.question.moneySafe': 'Meu dinheiro está seguro?',
  'help.answer.moneySafe': 'Sim! Usamos criptografia de nível bancário e medidas de segurança. Seus fundos são protegidos com autenticação biométrica e todas as transações são criptografadas.',
  'help.question.sendMoney': 'Como envio dinheiro?',
  'help.answer.sendMoney': 'Toque no botão "Enviar" na tela da carteira, insira o ID da carteira do destinatário ou escaneie o código QR, insira o valor e confirme.',
