  'help.answer.virtualCards': 'Cartões virtuais são números de cartão temporários que você pode usar para compras online. Eles ajudam a proteger sua carteira principal contra fraudes.',
  'help.question.virtualCardsFree': 'Os cartões virtuais são gratuitos?',
  'help.answer.virtualCardsFree': 'Sim, os cartões virtuais são gratuitos para criar. Você pode usá-los para compras online e assinaturas digitais. Os limites de gastos dependem do seu nível de conta.',
  'help.question.budgetsHelp': 'Como os orçamentos me ajudam?',
  'help.answer.budgetsHelp': "Os orçamentos ajudam você a acompanhar gastos por categoria. Defina limites mensais e receba alertas quando estiver perto do limite.",
  'help.question.receiveDifferentCurrencies': 'Posso receber dinheiro em diferentes moedas?',
